    "hjelp.sidetittel": "📖 Hjelp & bryggehåndbok",
    "hjelp.sidenavFaq": "📖 Hjelp & FAQ",
    "hjelp.sidenavBryggedag": "🗓️ En bryggedag",
    "hjelp.sidenavBryggemetoder": "⚗️ Bryggemetoder",
